// Des: Cloud page purge v2: packs, guards, breaker, two-phase delete
// Flo: resume half-done purges > at the high mark take old daily packs (runs/, min age, max share per run) > move still-latest files into one keep/ pack (verified, copied) > manifest to the cloud DB > mark purging > delete > mark purged; keep packs with too much dead weight are rewritten
// I/O: Sync (store + sql + local Db + optional copy store) + cap bytes (caller) > Pres; parsed records are never touched; dryz only counts
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const outb = @import("sy-clou-outb.zig"); const pack = @import("ru-purg-pack.zig"); const file = @import("st-stor-file.zig");
const CF = .{ .dayz = 86400000, .maxp = 64 << 20 };
pub const Actz = enum { none, purged, upgr, young };
pub const Pres = struct { act2: Actz = .none, usa2: u64 = 0, cap2: u64 = 0, fre3: u64 = 0, pac4: u32 = 0, kept: u32 = 0, keep: u32 = 0, comp: u32 = 0, bads: u32 = 0, limd: bool = false, plan: bool = false };
const Lent = struct { hexz: []const u8, offs: i64, lenz: i64 };
const Dele = struct { key2: []const u8, size: u64, ents: usize };
const Shar = struct { live: u32 = 0, dead: u64 = 0, tota: u64 = 0 };
fn lessKeyz(_: void, left: stor.Objz, rite: stor.Objz) bool { return std.mem.lessThan(u8, left.key2, rite.key2); }
fn entsLoca(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8) ![]Lent { var stmt = try self.dbzz.prep("SELECT hexz,offs,lenz FROM pack WHERE packk=?1;"); defer stmt.fini(); try stmt.bindText(1, key2); var list: std.ArrayList(Lent) = .empty; while (try stmt.step()) try list.append(aren, .{ .hexz = try aren.dupe(u8, stmt.colzText(0)), .offs = stmt.colzIntz(1), .lenz = stmt.colzIntz(2) }); return list.toOwnedSlice(aren); }
fn iszzLive(self: *sync.Sync, hexz: []const u8) !bool { var stmt = try self.dbzz.prep("SELECT 1 FROM page WHERE hexz=?1 LIMIT 1;"); defer stmt.fini(); try stmt.bindText(1, hexz); return try stmt.step(); }
fn deadShar(self: *sync.Sync, ents: []const Lent) !Shar { var shar: Shar = .{}; for (ents) |entr| { shar.tota += @intCast(entr.lenz); if (try iszzLive(self, entr.hexz)) { shar.live += 1; } else shar.dead += @intCast(entr.lenz); } return shar; }
fn purgSetz(self: *sync.Sync, key2: []const u8, ents: usize, nowz: i64, stat: i64) !void { var stmt = try self.dbzz.prep("INSERT INTO purg(packz,timz,ents,stat) VALUES(?1,?2,?3,?4) ON CONFLICT(packz) DO UPDATE SET timz=?2,ents=?3,stat=?4;"); defer stmt.fini(); try stmt.bindText(1, key2); try stmt.bindIntz(2, nowz); try stmt.bindIntz(3, @intCast(ents)); try stmt.bindIntz(4, stat); _ = try stmt.step(); }
fn getzPack(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8) ![]u8 { return self.store.get(self.store.ctx2, aren, self.iozz, key2) catch |err3| { const cop2 = self.copy orelse return err3; if (pack.packGenz(key2) != 1) return err3; return cop2.get(cop2.ctx2, aren, self.iozz, key2); }; }
fn gathMove(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8, ents: []const Lent, move: *std.ArrayList(pack.Part)) !bool { var live: usize = 0; for (ents) |entr| { if (try iszzLive(self, entr.hexz)) live += 1; } if (live == 0) return true; const mark = move.items.len; const byts = getzPack(self, aren, key2) catch return false; for (ents) |entr| { if (!try iszzLive(self, entr.hexz)) continue; const offs: usize = @intCast(entr.offs); const lenz: usize = @intCast(entr.lenz); if (offs + lenz <= byts.len and pack.partOkay(aren, entr.hexz, byts[offs .. offs + lenz])) { try move.append(aren, .{ .hexz = entr.hexz, .gzzz = byts[offs .. offs + lenz] }); continue; } const rawd = try std.fs.path.join(aren, &.{ self.dirz, "raw" }); const body = file.fileLoad(aren, self.iozz, rawd, entr.hexz[0..64].*, CF.maxp) catch { move.shrinkRetainingCapacity(mark); return false; }; try move.append(aren, .{ .hexz = entr.hexz, .gzzz = try file.gzipPack(aren, body) }); } return true; }
fn takeMove(self: *sync.Sync, aren: std.mem.Allocator, key2: []const u8, move: *std.ArrayList(pack.Part), rslt: *Pres) !bool { const ents = try entsLoca(self, aren, key2); if (self.dryz) { const shar = try deadShar(self, ents); rslt.kept += shar.live; return true; } return gathMove(self, aren, key2, ents, move); }
fn delzPack(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64, key2: []const u8) !void { try self.store.del2(self.store.ctx2, aren, self.iozz, key2); if (pack.packGenz(key2) == 1) { if (self.copy) |cop2| cop2.del2(cop2.ctx2, aren, self.iozz, key2) catch {}; } const clrz = [_][]const u8{try std.fmt.allocPrint(aren, "DELETE FROM cl_manif WHERE pack={s}", .{try sqlz.litz(aren, self.sql2.dial, key2)})}; self.sql2.exec(self.sql2.ctx2, aren, self.iozz, &clrz) catch {}; var del2 = try self.dbzz.prep("DELETE FROM pack WHERE packk=?1;"); defer del2.fini(); try del2.bindText(1, key2); _ = try del2.step(); try purgSetz(self, key2, 0, nowz, 1); }
fn resuPurg(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64) !void { var stmt = try self.dbzz.prep("SELECT packz FROM purg WHERE stat=0;"); defer stmt.fini(); var list: std.ArrayList([]const u8) = .empty; while (try stmt.step()) try list.append(aren, try aren.dupe(u8, stmt.colzText(0))); for (list.items) |key2| try delzPack(self, aren, nowz, key2); }
fn copyRetr(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64) !void { const cop2 = self.copy orelse return; const duez = try outb.outbDuez(self.dbzz, aren, "copy", nowz, 50); for (duez) |item| { var stmt = try self.dbzz.prep("SELECT 1 FROM pack WHERE packk=?1 LIMIT 1;"); defer stmt.fini(); try stmt.bindText(1, item.keyz); if (!try stmt.step()) { try outb.outbDone(self.dbzz, "copy", item.keyz); continue; } const byts = self.store.get(self.store.ctx2, aren, self.iozz, item.keyz) catch |err3| { try outb.outbFail(self.dbzz, "copy", item.keyz, @errorName(err3), nowz); continue; }; cop2.put(cop2.ctx2, aren, self.iozz, item.keyz, byts) catch |err3| { try outb.outbFail(self.dbzz, "copy", item.keyz, @errorName(err3), nowz); continue; }; try outb.outbDone(self.dbzz, "copy", item.keyz); } }
fn maniDels(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64, dels: []const Dele, stmz: *std.ArrayList([]const u8)) !void { for (dels) |dele| { const mani = [_]sqlz.Colz{ .{ .name = "packz", .valu = try sqlz.litz(aren, self.sql2.dial, dele.key2) }, .{ .name = "timz", .valu = try std.fmt.allocPrint(aren, "{d}", .{nowz}) }, .{ .name = "ents", .valu = try std.fmt.allocPrint(aren, "{d}", .{dele.ents}) } }; try stmz.append(aren, try sqlz.upse(aren, self.sql2.dial, "cl_purg", "packz", &mani)); } }
fn keepWrit(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64, move: []const pack.Part, dels: []const Dele) !usize { const byts = try pack.packBuil(aren, move); const ents = try pack.packPars(aren, byts); const key2 = try pack.packName(aren, pack.CF.keep, nowz, byts); try self.store.put(self.store.ctx2, aren, self.iozz, key2, byts); const objs = try self.store.list(self.store.ctx2, aren, self.iozz, key2); var good = false; for (objs) |obj2| { if (std.mem.eql(u8, obj2.key2, key2) and obj2.size == byts.len) good = true; } if (!good) return error.CloudHttp; if (self.conf.purg_copy_enab) { if (self.copy) |cop2| { cop2.put(cop2.ctx2, aren, self.iozz, key2, byts) catch try outb.outbAddz(self.dbzz, "copy", key2, nowz, true); } }
var stmz: std.ArrayList([]const u8) = .empty; for (ents) |entr| { const cols = [_]sqlz.Colz{ .{ .name = "hexz", .valu = try sqlz.litz(aren, self.sql2.dial, entr.hexz) }, .{ .name = "pack", .valu = try sqlz.litz(aren, self.sql2.dial, key2) }, .{ .name = "offs", .valu = try std.fmt.allocPrint(aren, "{d}", .{entr.offs}) }, .{ .name = "lenz", .valu = try std.fmt.allocPrint(aren, "{d}", .{entr.lenz}) } }; try stmz.append(aren, try sqlz.upse(aren, self.sql2.dial, "cl_manif", "hexz", &cols)); } try maniDels(self, aren, nowz, dels, &stmz); try self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items);
try self.dbzz.exec("BEGIN IMMEDIATE;"); errdefer self.dbzz.exec("ROLLBACK;") catch {}; for (ents) |entr| { var updz = try self.dbzz.prep("UPDATE pack SET packk=?2,offs=?3,lenz=?4,vend=?5,vfyz=?6 WHERE hexz=?1;"); defer updz.fini(); try updz.bindText(1, entr.hexz); try updz.bindText(2, key2); try updz.bindIntz(3, @intCast(entr.offs)); try updz.bindIntz(4, @intCast(entr.lenz)); try updz.bindText(5, self.vnam); try updz.bindIntz(6, nowz); _ = try updz.step(); } for (dels) |dele| try purgSetz(self, dele.key2, dele.ents, nowz, 0); try self.dbzz.exec("COMMIT;"); return byts.len; }
pub fn purgRunz(self: *sync.Sync, aren: std.mem.Allocator, nowz: i64, capb: u64) !Pres { var rslt: Pres = .{ .cap2 = capb, .plan = self.dryz }; if (!self.dryz) { try resuPurg(self, aren, nowz); try copyRetr(self, aren, nowz); } const lis0 = try self.store.list(self.store.ctx2, aren, self.iozz, pack.CF.runs); const lis1 = try self.store.list(self.store.ctx2, aren, self.iozz, pack.CF.keep); var usa2: u64 = 0; for (lis0) |obj2| usa2 += obj2.size; for (lis1) |obj2| usa2 += obj2.size; rslt.usa2 = usa2; const conf = self.conf; const high = capb * conf.purg_high_pctz / 100; const lowz = capb * conf.purg_lowz_pctz / 100; const maxb = capb * conf.purg_maxx_pctz / 100; if (capb > 0 and usa2 >= high and std.mem.eql(u8, conf.clou_poli_mode, "upgr")) { rslt.act2 = .upgr; return rslt; }
var dels: std.ArrayList(Dele) = .empty; var move: std.ArrayList(pack.Part) = .empty; var free: u64 = 0; if (capb > 0 and usa2 >= high) { std.mem.sort(stor.Objz, lis0, {}, lessKeyz); for (lis0) |obj2| { if (usa2 - free <= lowz) break; if (free >= maxb) { rslt.limd = true; break; } const dtzz = pack.packDate(obj2.key2) orelse continue; if (nowz - dtzz < @as(i64, conf.purg_clou_mini_days) * CF.dayz) continue; if (!try takeMove(self, aren, obj2.key2, &move, &rslt)) { rslt.bads += 1; continue; } try dels.append(aren, .{ .key2 = obj2.key2, .size = obj2.size, .ents = (try entsLoca(self, aren, obj2.key2)).len }); free += obj2.size; } if (dels.items.len == 0) rslt.act2 = .young; }
for (lis1) |obj2| { const ents = try entsLoca(self, aren, obj2.key2); const shar = try deadShar(self, ents); if (ents.len > 0 and shar.dead * 100 <= shar.tota * conf.purg_dead_pctz) continue; if (!try takeMove(self, aren, obj2.key2, &move, &rslt)) { rslt.bads += 1; continue; } try dels.append(aren, .{ .key2 = obj2.key2, .size = obj2.size, .ents = ents.len }); free += obj2.size; rslt.comp += 1; }
rslt.pac4 = @intCast(dels.items.len); rslt.fre3 = free; if (dels.items.len > 0) rslt.act2 = .purged; if (self.dryz or dels.items.len == 0) return rslt; var keep: usize = 0; if (move.items.len > 0) { keep = try keepWrit(self, aren, nowz, move.items, dels.items); rslt.keep = 1; rslt.kept = @intCast(move.items.len); } else { var stmz: std.ArrayList([]const u8) = .empty; try maniDels(self, aren, nowz, dels.items, &stmz); try self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items); for (dels.items) |dele| try purgSetz(self, dele.key2, dele.ents, nowz, 0); } for (dels.items) |dele| try delzPack(self, aren, nowz, dele.key2); rslt.usa2 = usa2 - free + keep; return rslt; }
